struct RustKernelDemo;

impl kernel::Module for RustKernelDemo {
    fn init(_name: &'static CStr, _module: &'static ThisModule) -> Result<Self> {
        pr_info!("Rust kernel module initialized with strict memory safety\n");
        Ok(RustKernelDemo)
